<section class="panel" id="attachments"><h3>Pièces jointes</h3><div data-attachment-list><?php foreach($attachments as $a): ?><div class="attachment-row" data-attachment-id="<?= (int)$a['id'] ?>"><a class="attachment" href="/attachments/<?= (int)$a['id'] ?>"><?= icon('download') ?><span><?= e($a['original_name']) ?><small><?= number_format($a['size_bytes']/1024,0,',',' ') ?> Ko</small></span></a><?php if($user['role']!=='viewer'): ?><form method="post" action="/attachments/<?= (int)$a['id'] ?>/delete"><?= csrf() ?><?= ticket_context() ?><button class="tiny-button danger" aria-label="Supprimer <?= e($a['original_name']) ?>" data-confirm="Supprimer définitivement cette pièce jointe ? Elle disparaîtra aussi des images de la conversation.">×</button></form><?php endif; ?></div><?php endforeach; ?></div><?php if($user['role']!=='viewer'): ?><form method="post" enctype="multipart/form-data" action="/tickets/<?= (int)$ticket['id'] ?>/attachments" class="stack" data-file-queue><?= csrf() ?><?= ticket_context() ?><input type="hidden" name="_return" value="<?= e(ticket_url((int)$ticket['id'])) ?>"><label class="file-dropzone" data-dropzone>Déposez vos fichiers ici<span>ou choisissez des fichiers</span><input type="file" name="files[]" multiple required></label><small><?= (int)env('UPLOAD_MAX_MB','10') ?> Mo maximum par fichier · 20 fichiers maximum par envoi</small><ul class="pending-files" data-pending-files></ul><button class="button subtle small-button" data-upload-submit hidden>Joindre les fichiers</button><p role="status" aria-live="polite" data-upload-status></p></form><?php endif; ?></section>
<section class="panel" id="relations"><h3>Tickets liés</h3><?php foreach($links as $link): ?><div class="linked-ticket"><a href="<?= e(ticket_url((int)$link['target_id'])) ?>"><small><?= e(['relates'=>'Associé à','blocks'=>'Bloque','duplicates'=>'Doublon de'][$link['relation']]) ?></small><?= e($link['project_key'].'-'.$link['number'].' · '.$link['title']) ?></a><?php if($user['role']!=='viewer'): ?><form method="post" action="/links/<?= (int)$link['id'] ?>/delete"><?= csrf() ?><?= ticket_context() ?><button class="tiny-button" aria-label="Retirer la relation">×</button></form><?php endif; ?></div><?php endforeach; if($user['role']!=='viewer'): ?><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/links" class="stack"><?= csrf() ?><?= ticket_context() ?><input type="hidden" name="_return" value="<?= e(ticket_url((int)$ticket['id'])) ?>"><select name="relation"><option value="relates">Associé à</option><option value="blocks">Bloque</option><option value="duplicates">Doublon de</option></select><select name="target_id" required><option value="">Choisir un ticket</option><?php foreach($parents as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($project['project_key'].'-'.$p['number'].' · '.$p['title']) ?></option><?php endforeach; ?></select><button class="button subtle small-button">Associer</button></form><?php endif; ?></section>
<?php if($children): ?><section class="panel"><h3>Tickets enfants</h3><?php foreach($children as $child): ?><a class="child-ticket" href="<?= e(ticket_url((int)$child['id'])) ?>"><span class="legend-dot status-<?= e($child['status']) ?>"></span><?= e($child['title']) ?></a><?php endforeach; ?></section><?php endif; ?>
<?php if(!$ticket['archived']&&$user['role']!=='viewer'): ?><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/archive"><?= csrf() ?><?= ticket_context() ?><button class="button danger-outline" data-confirm="Archiver ce ticket ? Il sera retiré des listes et du tableau. Vous pourrez le restaurer depuis sa fiche.">Archiver ce ticket</button></form><?php endif; ?>
